VALUES ('cff3f57d-d532-4f96-97e5-d56aa1bfe581'::uuid, 'a534cebc-a7a9-4aa4-b676-f51bc5f3634d'::uuid, 'artist', 'f01002fa-68e4-4fa9-a8cc-91ab9004cea9'::uuid)
ON CONFLICT DO NOTHING;

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Wilfrido Radhamés Vargas Martínez (born 24 April 1949) is a Dominican trumpeter, bandleader, composer, arranger and producer, and one of the principal architects of modern merengue. Where earlier bandleaders modernised the genre at home, Vargas built the orchestra that carried it abroad: he absorbed Haitian kompa and other Afro-Antillean currents into its rhythmic language, staged merengue as choreographed spectacle, and founded a run of ensembles and launched a run of singers that together defined the genre''s commercial peak in the 1980s. The Latin Recording Academy gave him its Musical Excellence Award in 2018.","type":"text"}]},{"type":"paragraph","content":[{"text":"Early years and formation","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Vargas was born in Altamira, a rural municipality in the province of Puerto Plata. Music at home came from both parents: his mother, Bienvenida Martínez, played guitar and flute, and his father, Ramón Vargas, was an accordionist and guitarist. At ten he entered the municipal academy of music in Altamira, where he studied solfège and theory. He started on guitar but moved quickly to the trumpet, and by eleven was the municipal band''s principal trumpeter, an unusual chair for a boy of that age and an early measure of his technique.","type":"text"}]},{"type":"paragraph","content":[{"text":"As an adolescent he worked as a postal carrier alongside his playing, the two jobs together a fair measure of what a rural musician could earn in the Dominican Republic at mid-century. When administrative changes cost him both, he left for Santo Domingo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Professional beginnings in Santo Domingo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In the capital he entered the working circuit of bars, theatres and merengue ensembles: Bar Herminia, where he made his professional debut on trumpet, the Teatro Stella, and then the orchestras of Paniagua Rodríguez and Rafael Mancebo. These were traditional groups playing the format that prevailed before the modernisation Vargas would help drive, and they earned him a reputation as a trumpeter equally capable in section work and as a soloist.","type":"text"}]},{"type":"paragraph","content":[{"text":"Wilfrido Vargas y sus Beduinos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1972 he founded Wilfrido Vargas y sus Beduinos and recorded his first album with them. The group turned him from instrumentalist into bandleader and became the laboratory for everything that followed: enlarged brass, choreographed staging, and rhythmic structures borrowed from across the Caribbean. It was also a training ground — ","type":"text"},{"type":"artistReference","attrs":{"artistId":"4b4bf9da-fe4a-4fc6-be40-1b1b5413dfb3","displayText":"Víctor Víctor","occurrenceId":"381e57b1-d028-453c-b9d7-3dbc1fa159f1"}},{"text":" was among the singers who passed through it in the early years.","type":"text"}]},{"type":"paragraph","content":[{"text":"Haitian kompa and the remaking of merengue","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The decisive turn in Vargas''s writing came through Haitian kompa, and particularly through Tabou Combo and DP Express. Their rhythmic and harmonic thinking reshaped his approach to merengue and pushed him to fold Afro-Antillean material into Dominican dance music systematically rather than as ornament. The orchestral sound that resulted was built on syncopated rhythmic layering, polyphonic vocal arrangements, hybrid horn writing, kompa-derived harmonic movement, and a theatrical, choreographed stage presentation.","type":"text"}]},{"type":"paragraph","content":[{"text":"The work ran parallel to the earlier modernisation of merengue by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3f8bafec-e5ee-415d-8405-9551cceeeb9b","displayText":"Johnny Ventura","occurrenceId":"77335bfe-c2c4-4b51-b5bf-dd8eea8b7493"}},{"text":", but it was not the same project. Ventura brought showmanship and a widened instrumentation to a national audience; Vargas brought cross-currents from outside the country, and a sound engineered to travel.","type":"text"}]},{"type":"paragraph","content":[{"text":"International expansion","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"From the late 1970s Vargas was among the most visible Dominican artists working abroad. His appearances included Madison Square Garden in 1976, the Havana Jam festival in Cuba in 1979, and Altos de Chavón, where his was the first Dominican orchestra to fill the amphitheatre, alongside touring through Europe, Mexico, South America and the United States. The records of this period paired intricate arrangements with humour and narrative dramatisation, and they did much to make merengue a dominant dance music across Latin America.","type":"text"}]},{"type":"paragraph","content":[{"text":"Major recordings","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"El Barbarazo — 1978, his first international hit","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Abusadora — 1981","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"El Africano — 1984","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"El Jardinero — 1984","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"La Medicina — 1985","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"El Baile del Perrito — 1989, from the album Itinerario","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Comején, A Mover la Colita, El Loco y la Luna and Volveré, all of which remain in the merengue canon","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Ensembles he created and directed","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Beyond his own orchestra, Vargas founded and directed groups that widened what merengue could be:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"6778e4a3-8f63-420f-bdd4-9a0a7e5cacc5","displayText":"Las Chicas del Can","occurrenceId":"f35e7027-cb02-48a7-816c-c30d968a47ab"}},{"text":" — among the first women''s merengue groups to succeed internationally","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"2dde2335-84c3-49ba-be43-f3c3ae717d87","displayText":"The New York Band","occurrenceId":"95fc7795-8e20-46f6-bed8-2b1ff3d13c17"}},{"text":" — merengue crossed with pop, rock and urban material","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"e735658a-0cc6-4238-9cf9-e5bebad6724b","displayText":"Altamira Banda Show","occurrenceId":"c6d48718-fdbf-4f81-865a-d86568a2f735"}},{"text":" — built around theatrical staging and choreography","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"The singers he trained","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Vargas''s orchestras were the way into the profession for a generation of Dominican vocalists. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"0ab9fdf6-61d3-439e-8548-35c370eaf87d"}},{"text":" sang with the Beduinos from 1982 to 1987, and his recording of Volveré — a song that had first been intended for another singer in the group, Jorge Gómez — became one of the orchestra''s largest successes and established him as a soloist. Eddie Herrera, Juancho Viloria and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"4b4bf9da-fe4a-4fc6-be40-1b1b5413dfb3","displayText":"Víctor Víctor","occurrenceId":"9ff264ee-f1e7-4079-b4ea-b2018b4bd0c0"}},{"text":" also came up through the ensembles. What shaped them was Vargas''s rehearsal discipline, his insistence on vocal precision and his ear, and the standard he set became a working model for professional merengue orchestras.","type":"text"}]},{"type":"paragraph","content":[{"text":"Recognition","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Order of Christopher Columbus, Knight grade — conferred in 1993 by President ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f01002fa-68e4-4fa9-a8cc-91ab9004cea9","displayText":"Joaquín Balaguer","occurrenceId":"a87df7df-045e-4b86-b878-65e26ba86d0f"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Grammy nomination, Best Tropical Latin Performance — 1991, for Animation","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Musical Excellence Award, Latin Recording Academy — 2018, presented to him by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3f8bafec-e5ee-415d-8405-9551cceeeb9b","displayText":"Johnny Ventura","occurrenceId":"e6ec9a9f-a3ef-48fb-a005-d1e563c9b281"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gold and platinum certifications across five decades of releases","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Vargas is one of the figures the modern history of merengue cannot be written without. He rebuilt the orchestra, opened the genre to Afro-Antillean influence, created the ensembles that carried it into new markets, and trained many of the voices that sang it. The transformation of merengue from a national music into a transnational one was not his work alone, but it is not describable without him, and his catalogue remains a standing reference in Caribbean music.","type":"text"}]}]}'::jsonb,
       revision = 4, updated_at = now() WHERE id = 'bca898c8-2574-4e08-9ebf-e1803f587af0'::uuid;
