VALUES ('bca898c8-2574-4e08-9ebf-e1803f587af0'::uuid, 'a87df7df-045e-4b86-b878-65e26ba86d0f'::uuid, 'artist', 'f01002fa-68e4-4fa9-a8cc-91ab9004cea9'::uuid)
